def transform(g):
    h,w=len(g),len(g[0]); out=[row[:] for row in g]
    from collections import deque
    bg=g[0][0]
    seen=[[False]*w for _ in range(h)]
    # flood fill background from outside; only bg-colored cells
    dq=deque((i,j) for i in range(h) for j in (0,w-1)) 
    dq.extend((0,j) for j in range(w)); dq.extend((h-1,j) for j in range(w))
    for i,j in dq:
        if g[i][j]==bg: seen[i][j]=True
    while dq:
        i,j=dq.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and not seen[a][b] and g[a][b]==bg:
                seen[a][b]=True; dq.append((a,b))
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]: out[i][j]=7
    return out
