def enclosed_regions(grid, color=None):
    """The connected regions of `color` (default: background) not reachable from the border."""
    if color is None:
        color = background(grid)
    H, W = len(grid), len(grid[0])
    outside = flood_from_border(grid, color)
    rest = {(i, j) for i in range(H) for j in range(W)
            if grid[i][j] == color and (i, j) not in outside}
    regs = []
    while rest:
        c = rest.pop()
        reg = {c}
        q = deque([c])
        while q:
            i, j = q.popleft()
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                n = (i + di, j + dj)
                if n in rest:
                    rest.discard(n)
                    q.append(n)
                    reg.add(n)
        regs.append(reg)
    return regs

def fill_rect_holes(grid, new=4):
    """Fill every enclosed background region that is a solid rectangle with color `new`."""
    out = [row[:] for row in grid]
    for reg in enclosed_regions(grid):
        if is_solid_rect(reg):
            for i, j in reg:
                out[i][j] = new
    return out

